const rows = $input.all().map(i => i.json)

// Mapping de build → versión humana
function osHumanLabel(os, version) {
  if (!os) return 'Desconocido'
  const o = String(os)
  const v = String(version || '')
  // Win 11 builds
  if (v.startsWith('10.0.26')) return o + ' · 25H2'
  if (v.startsWith('10.0.22631')) return o + ' · 23H2'
  if (v.startsWith('10.0.22621')) return o + ' · 22H2'
  if (v.startsWith('10.0.22000')) return o + ' · 21H2'
  // Win 10 builds
  if (v.startsWith('10.0.19045')) return o + ' · 22H2'
  if (v.startsWith('10.0.19044')) return o + ' · 21H2'
  if (v.startsWith('10.0.19043')) return o + ' · 21H1'
  if (v.startsWith('10.0.19042')) return o + ' · 20H2'
  if (v.startsWith('10.0.19041')) return o + ' · 2004'
  if (v.startsWith('10.0.18363')) return o + ' · 1909'
  if (v.startsWith('10.0.17763')) return o + ' · 1809 LTSC'
  if (v.startsWith('10.0.14393')) return o + ' · 1607 LTSB'
  // Win 7 / 8
  if (v.startsWith('6.1.7601')) return o + ' SP1 (EOL)'
  // Server
  if (v.startsWith('10.0.20348')) return o + ' (Server 2022)'
  if (v.startsWith('10.0.17763')) return o + ' (Server 2019)'
  if (v.startsWith('10.0.14393')) return o + ' (Server 2016)'
  if (v) return o + ' · ' + v
  return o
}

if (!rows.length) return [{ json: { name: 'inventario', skip: true } }]

const isServer = (os) => /server\b/i.test(os || '')
// EOL: todo SO < Windows 11 = fin de vida útil (sincronizado con cross-ref.ts EOL_KEYWORDS)
const EOL_CLIENT = [/windows xp/i, /windows vista/i, /windows 7/i, /windows 8\b/i, /windows 8\.1/i, /windows 10/i]
const EOL_SERVER = [/server 2003/i, /server 2008/i, /server 2012/i]
const isEol = (os) => {
  if (!os) return false
  const arr = isServer(os) ? EOL_SERVER : EOL_CLIENT
  return arr.some(p => p.test(os))
}
const STALE_MS = 30 * 24 * 3600 * 1000
const isStale = (r) => {
  if (!r.ocs_last_contact) return true
  return (Date.now() - new Date(r.ocs_last_contact).getTime()) > STALE_MS
}
const cleanOs = (os) => os ? os.replace(/^Microsoft /,'').replace(/ Edition$/,'').slice(0, 50) : 'Desconocido'

// SMART health: parse "Bueno (85 %)" → 85
function smartHealthPct(s) {
  if (!s) return null
  const m = String(s).match(/(\d+)\s*%/)
  return m ? parseInt(m[1], 10) : null
}

// Per-equipment criteria evaluation
function evaluateCriteria(r) {
  const isW11 = /windows 11/i.test(r.os || '')
  const isWinServer = isServer(r.os)
  const ram_ok = (r.ram_mb || 0) >= 8192
  // Disco desconocido (no reportado) → null: no suma ni resta al score. Solo HDD confirmado penaliza.
  const ssd_ok = r.disk_type === 'SSD' ? true : (r.disk_type === 'HDD' ? false : null)
  const disk_ok = r.disk_used_pct == null ? null : (r.disk_used_pct < 90)
  const smartPct = smartHealthPct(r.disk_health)
  const smart_ok = smartPct == null ? null : (smartPct >= 70)
  const cores_ok = (r.cpu_cores || 0) >= 4
  // Updates: <90 días desde last_kb_update
  let updates_ok = null
  if (r.last_kb_update) {
    const days = (Date.now() - new Date(r.last_kb_update).getTime()) / (24*3600*1000)
    updates_ok = days < 90
  }
  const eset_ok = !!r.eset_uuid
  const os_ok = !isEol(r.os) && (isWinServer || isW11)
  // OS rule: para servidores no exigimos Win11, solo no-EOL. Para clientes, Win11 (no EOL).

  return {
    os_ok,            // 20 pts
    ram_ok,           // 15 pts
    ssd_ok,           // 15 pts
    disk_ok,          // 10 pts (null si no hay data)
    smart_ok,         // 10 pts (null si no hay data)
    cores_ok,         // 10 pts
    updates_ok,       // 10 pts (null si no hay data)
    eset_ok,          // 10 pts
  }
}

// Score per equipment: pesos del usuario
const WEIGHTS = {
  os_ok: 20, ram_ok: 15, ssd_ok: 15, disk_ok: 10,
  smart_ok: 10, cores_ok: 10, updates_ok: 10, eset_ok: 10,
}

function scoreFor(crit) {
  // Si un criterio es null (sin data), lo excluimos del divisor (no penaliza)
  let achieved = 0
  let possible = 0
  for (const [k, w] of Object.entries(WEIGHTS)) {
    const v = crit[k]
    if (v === null || v === undefined) continue
    possible += w
    if (v === true) achieved += w
  }
  if (possible === 0) return 0
  return Math.round((achieved / possible) * 100)
}

// Process every row: attach criteria + score
const processed = rows.map(r => {
  const criteria = evaluateCriteria(r)
  const score = scoreFor(criteria)
  return { ...r, criteria, score, _server: isServer(r.os), _stale: isStale(r), _eol: isEol(r.os) }
})

// Counts per criterion (only over non-stale + non-null)
function countCriterion(list, key) {
  const evaluable = list.filter(r => !r._stale && r.criteria[key] !== null && r.criteria[key] !== undefined)
  const cumplen  = evaluable.filter(r => r.criteria[key] === true).length
  return { evaluable: evaluable.length, cumplen }
}

function statsFor(list) {
  const total = list.length
  const stale = list.filter(r => r._stale).length
  const activos = total - stale
  const scores = list.filter(r => !r._stale).map(r => r.score)
  const avgScore = scores.length ? Math.round(scores.reduce((s,x)=>s+x,0)/scores.length) : 0
  const ok       = scores.filter(s => s >= 70).length
  const atencion = scores.filter(s => s >= 50 && s < 70).length
  const critico  = scores.filter(s => s < 50).length
  const eol = list.filter(r => r._eol).length
  return {
    total, stale, activos, eol, avgScore, ok, atencion, critico,
    criterios: {
      os: countCriterion(list, 'os_ok'),
      ram: countCriterion(list, 'ram_ok'),
      ssd: countCriterion(list, 'ssd_ok'),
      disk: countCriterion(list, 'disk_ok'),
      smart: countCriterion(list, 'smart_ok'),
      cores: countCriterion(list, 'cores_ok'),
      updates: countCriterion(list, 'updates_ok'),
      eset: countCriterion(list, 'eset_ok'),
    }
  }
}

const clientes  = processed.filter(r => !r._server)
const servidores = processed.filter(r => r._server)
const C = statsFor(clientes)
const S = statsFor(servidores)

// Combined module score: weighted by counts (clients pesan más)
const allActive = processed.filter(r => !r._stale)
const moduleScore = allActive.length
  ? Math.round(allActive.reduce((s,r) => s + r.score, 0) / allActive.length)
  : 0

// OS distribution
const osCounts = {}
processed.forEach(r => {
  const k = cleanOs(r.os)
  osCounts[k] = (osCounts[k]||0)+1
})
const sistOperativos = Object.entries(osCounts)
  .sort((a,b) => b[1]-a[1]).slice(0, 8)
  .map(([label,value]) => ({ label, value }))

// Score distribution chart
const distribOk = allActive.filter(r => r.score >= 70).length
const distribAt = allActive.filter(r => r.score >= 50 && r.score < 70).length
const distribCr = allActive.filter(r => r.score < 50).length
const scoreDistribution = []
if (distribOk > 0) scoreDistribution.push({ label: 'OK (≥70)',       value: distribOk, color: '#43C961' })
if (distribAt > 0) scoreDistribution.push({ label: 'Atención (50-69)', value: distribAt, color: '#d4900a' })
if (distribCr > 0) scoreDistribution.push({ label: 'Crítico (<50)',   value: distribCr, color: '#F05754' })

// Table rows: simplified for UI
const tabla = processed.map(r => ({
  hostname: r.hostname || '?',
  os: cleanOs(r.os),
  os_raw: r.os || '',
  os_version: r.os_version || '',
  os_human: osHumanLabel(cleanOs(r.os), r.os_version),
  kb_count_30d: r.kb_count_30d || null,
  is_server: r._server,
  eol: r._eol,
  stale: r._stale,
  ram_mb: r.ram_mb || 0,
  cpu_cores: r.cpu_cores || 0,
  cpu_speed_mhz: r.cpu_speed_mhz || 0,
  disk_gb: r.disk_gb || 0,
  disk_type: r.disk_type || null,
  disk_used_pct: r.disk_used_pct,
  disk_health: r.disk_health,
  disk_hours_on: r.disk_hours_on,
  cpu: r.cpu || '',
  ip: r.ip || '',
  user: r.user || r.ocs_username || '',
  ocs_last_contact: r.ocs_last_contact || null,
  eset_status: r.eset_status || null,
  eset_last_seen: r.eset_last_seen || null,
  has_eset: !!r.eset_uuid,
  is_virtual: !!r.is_virtual,
  last_kb_update: r.last_kb_update || null,
  uptime_days: r.uptime_days,
  source: r.source || 'ocs-only',
  score: r.score,
  criteria: r.criteria,
}))


  // F4 — narrativas dual (vars precomputadas)
const _nTotal = processed.length;
const _nActivos = allActive.length;
const _nStale = _nTotal - _nActivos;
const _nEol = processed.filter(r => r._eol).length;
const _nEsetOk = processed.filter(r => r.eset_uuid).length;
const _nPctEset = _nTotal > 0 ? Math.round((_nEsetOk / _nTotal) * 100) : 0;
const narrative = `${_nTotal} dispositivos en inventario. ${_nEol} obsoletos (EOL), ${_nStale} sin contacto reciente. Cobertura ESET: ${_nPctEset}% (${_nEsetOk}/${_nTotal}). Score promedio: ${moduleScore}/100.`;
const narrativeClient = `Su parque cuenta con ${_nTotal} dispositivos relevados. ${_nEol === 0 ? 'No se detectaron equipos con sistemas operativos sin soporte.' : `Identificamos ${_nEol} ${_nEol === 1 ? 'equipo con sistema operativo' : 'equipos con sistemas operativos'} sin soporte vigente, que se recomienda actualizar.`} La cobertura de protección antimalware alcanza el ${_nPctEset}% del parque.`;

  return [{ json: {
  name: 'inventario',
  narrative,
  narrativeClient,
  score: moduleScore,
  metrics: {
    total: processed.length,
    activos: allActive.length,
    stale: processed.length - allActive.length,
    eolCount: processed.filter(r => r._eol).length,
    obsoletos: processed.filter(r => (r.ram_mb && r.ram_mb < 4096) || (r.cpu_cores && r.cpu_cores < 2)).length,
    esetOk: processed.filter(r => r.eset_uuid).length,
    sinEset: processed.length - processed.filter(r => r.eset_uuid).length,
    pctEsetOk: processed.length > 0 ? Math.round((processed.filter(r => r.eset_uuid).length / processed.length) * 100) : 0,
    avgScore: moduleScore,
    clientes: C,
    servidores: S,
  },
  charts: {
    scoreDistribution: scoreDistribution.length >= 2 ? scoreDistribution : [],
    sistOperativos: sistOperativos.length >= 2 ? sistOperativos : [],
  },
  tabla,
  ai_prompt: `Inventario: ${processed.length} equipos (${C.total} clientes, ${S.total} servidores). Score promedio ${moduleScore}/100. ${C.criterios.ssd.cumplen}/${C.criterios.ssd.evaluable} clientes con SSD, ${C.criterios.ram.cumplen}/${C.criterios.ram.evaluable} con RAM≥8GB.`,
} }]

function stripDomain(h) {
  if (!h) return '?'
  return String(h).split('.')[0].toUpperCase()
}

const detections = (() => { try { return $('sql_seguridad').all().map(i => i.json) } catch(_) { return $input.all().map(i => i.json) } })()

// Incidentes ESET (tenant-wide; deviceUuids siempre [] → no se bindean por host)
let incidentes = []
try { incidentes = $('sql_incidentes').all().map(i => i.json) } catch (_) {}

let totalDispositivos = 0, conEset = 0, sinEset = 0, reportandoReciente = 0
const statusDist = { OK: 0, WARN: 0, CRITICAL: 0, OTHER: 0 }
let inv = []
try {
  inv = $('sql_inventario').all().map(i => i.json)
  totalDispositivos = inv.length
  const cutoff = Date.now() - 30 * 24 * 3600 * 1000
  for (const r of inv) {
    if (r.eset_uuid) {
      conEset++
      const seen = r.eset_last_seen ? new Date(r.eset_last_seen).getTime() : 0
      if (seen >= cutoff) reportandoReciente++
      const st = String(r.eset_status || '').toUpperCase().trim()
      if (st === 'OK' || st === 'PROTECTED') statusDist.OK++
      else if (st === 'WARN' || st === 'WARNING' || st === 'ATTENTION') statusDist.WARN++
      else if (st === 'CRITICAL') statusDist.CRITICAL++
      else if (st) statusDist.OTHER++
    } else { sinEset++ }
  }
} catch (_) {}

if (conEset === 0 && incidentes.length === 0 && detections.length === 0) {
  return [{ json: { name: 'seguridad', skip: true } }]
}

const pctCobertura = totalDispositivos > 0 ? Math.round((conEset / totalDispositivos) * 100) : 0
const pctReportando = conEset > 0 ? Math.round((reportandoReciente / conEset) * 100) : 0

// ── Amenazas desde INCIDENTES (ESET incident-management v2) ──
function incSev(raw) {
  const s = String(raw || '').toUpperCase()
  if (s.includes('HIGH') || s.includes('CRITICAL')) return 'Crítica'
  if (s.includes('MEDIUM')) return 'Media'
  return 'Baja'
}
const amenazas = incidentes.length
const amenazasCriticas = incidentes.filter(i => incSev(i.severity) === 'Crítica').length

// ── Charts: SOLO cobertura general + estado ESET (Fase 3) ──
const estadoEset = Object.entries(statusDist).filter(([, v]) => v > 0).map(([label, value]) => ({
  label, value, color: label === 'OK' ? '#43C961' : label === 'WARN' ? '#d4900a' : label === 'CRITICAL' ? '#F05754' : '#888',
}))
const cobertura = [
  { label: 'Con ESET reportando', value: reportandoReciente, color: '#43C961' },
  { label: 'Sin reportar 30d', value: conEset - reportandoReciente, color: '#d4900a' },
  { label: 'Sin ESET', value: sinEset, color: '#F05754' },
].filter(x => x.value > 0)

// ── Detecciones por host (agrupadas por categoría) para anidar en cada equipo ──
function detSev(raw) {
  const s = String(raw || '').toUpperCase()
  if (s.includes('HIGH') || s.includes('CRITICAL')) return 'Crítica'
  if (s.includes('MEDIUM')) return 'Media'
  return 'Baja'
}
const SEVRANK = { 'Crítica': 3, 'Media': 2, 'Baja': 1 }
const detByInv = {}
for (const d of detections) {
  const key = String(d.inv_id)
  if (!detByInv[key]) detByInv[key] = {}
  const cat = d.category || 'Detección'
  const sev = detSev(d.severity)
  let g = detByInv[key][cat]
  if (!g) { g = detByInv[key][cat] = { host: stripDomain(d.hostname), category: cat, severity: sev, occurTime: d.occur_time || null, count: 0 } }
  g.count++
  if (SEVRANK[sev] > SEVRANK[g.severity]) g.severity = sev
  if (d.occur_time && (!g.occurTime || new Date(d.occur_time) > new Date(g.occurTime))) g.occurTime = d.occur_time
}

// ── Tablas unificadas (Fase 3) ──
const tablaConCobertura = []
const tablaSinCobertura = []
const cutoffSin = Date.now() - 30 * 24 * 3600 * 1000
for (const r of inv) {
  const cleanHost = stripDomain(r.hostname)
  if (r.eset_uuid) {
    const grupos = Object.values(detByInv[String(r.inv_id)] || {})
      .sort((a, b) => (SEVRANK[b.severity] - SEVRANK[a.severity]) || (b.count - a.count))
    const total = grupos.reduce((s, g) => s + g.count, 0)
    const crit = grupos.filter(g => g.severity === 'Crítica').reduce((s, g) => s + g.count, 0)
    const esetVer = Array.isArray(r.eset_products) && r.eset_products.length > 0
      ? (r.eset_products.find(p => p && p.length > 0) || null)
      : (r.eset_uuid ? 'instalado' : null)
    const stRaw = String(r.eset_status || '').toUpperCase().trim()
    const esetStatus = (stRaw === 'OK' || stRaw === 'PROTECTED') ? 'OK'
      : (stRaw === 'WARN' || stRaw === 'WARNING' || stRaw === 'ATTENTION') ? 'WARN'
        : (stRaw === 'CRITICAL') ? 'CRITICAL' : null
    tablaConCobertura.push({
      hostname: cleanHost,
      usuario: r.ocs_username || null,
      so: r.os || '?',
      soVersion: r.os_version || '',
      esetVersion: esetVer,
      esetStatus,
      estadoProteccion: r.eset_status || null,
      lastSeen: r.eset_last_seen || r.ocs_last_contact || null,
      deteccionesTotal: total,
      deteccionesCriticas: crit,
      detecciones: grupos.map(g => ({ host: g.host, category: g.category, severity: g.severity, occurTime: g.occurTime, count: g.count })),
      ram_mb: r.ram_mb != null ? Number(r.ram_mb) : undefined,
      disk_gb: r.disk_gb != null ? Number(r.disk_gb) : undefined,
      cpu: r.cpu || undefined,
    })
  } else {
    const last = r.ocs_last_contact ? new Date(r.ocs_last_contact).getTime() : 0
    if (last >= cutoffSin) {
      tablaSinCobertura.push({
        hostname: cleanHost,
        usuario: r.ocs_username || null,
        so: r.os || '?',
        soVersion: r.os_version || '',
        ocsLastContact: r.ocs_last_contact || null,
      })
    }
  }
}
tablaConCobertura.sort((a, b) => (b.deteccionesTotal - a.deteccionesTotal) || a.hostname.localeCompare(b.hostname))
tablaSinCobertura.sort((a, b) => a.hostname.localeCompare(b.hostname))

const _OK = statusDist.OK || 0, _WARN = statusDist.WARN || 0, _CRIT = statusDist.CRITICAL || 0
const narrative = `Cobertura ESET ${pctCobertura}% (${conEset}/${totalDispositivos}). ${reportandoReciente} reportaron en últimos 30d (${pctReportando}%). ${amenazas} incidentes de seguridad (${amenazasCriticas} de alta severidad). Estados: ${_OK} OK, ${_WARN} atención, ${_CRIT} crítico.`
const narrativeClient = `${pctCobertura}% del parque cuenta con protección antimalware activa y gestionada. ${pctReportando >= 90 ? 'La mayoría de los equipos protegidos reportaron su estado recientemente.' : `${pctReportando}% de los equipos protegidos reportaron su estado recientemente; el resto será revisado en las próximas visitas técnicas.`} ${amenazas === 0 ? 'No se registraron incidentes de seguridad en el período.' : `Se registraron ${amenazas} ${amenazas === 1 ? 'incidente' : 'incidentes'} de seguridad${amenazasCriticas > 0 ? `, de los cuales ${amenazasCriticas} ${amenazasCriticas === 1 ? 'fue de alta severidad y está bajo seguimiento' : 'fueron de alta severidad y están bajo seguimiento'}` : ''}.`}`

const score = Math.max(0, Math.min(100, pctCobertura * 0.5 + pctReportando * 0.3 - amenazasCriticas * 5 + (statusDist.OK / Math.max(1, conEset)) * 20))

return [{ json: {
  name: 'seguridad', narrative, narrativeClient, score: Math.round(score),
  metrics: {
    totalDispositivos, protegidos: conEset, sinEset, reportandoReciente, pctCobertura, pctReportando,
    amenazas, amenazasCriticas, statusOK: statusDist.OK, statusWARN: statusDist.WARN, statusCRITICAL: statusDist.CRITICAL,
  },
  charts: {
    cobertura,
    estadoEset: estadoEset.length >= 2 ? estadoEset : [],
  },
  tablaConCobertura,
  tablaSinCobertura,
  ai_prompt: `ESET ${pctCobertura}% cobertura. ${amenazas} incidentes (${amenazasCriticas} alta severidad). ${tablaSinCobertura.length} equipos sin cobertura.`,
} }]

const rowsRaw = $input.all().map(i => i.json)
if (!rowsRaw.length) return [{ json: { name: 'sla', skip: true } }]

// Filtrar borrados (defensive — el SQL ya filtra)
const rows = rowsRaw.filter(r => r.deleted !== true && r.deleted !== 't')

const RESOLVED_STATUSES = ['Closed', 'Resuelto', 'Cerrado/Para Entregar']
const HIGH_PRIORITIES   = ['High', 'Urgent', 'Alta']

const totalTickets = rows.length
const resueltos    = rows.filter(r => RESOLVED_STATUSES.includes(r.status)).length
const abiertos     = totalTickets - resueltos
const pctResolucion = totalTickets > 0 ? Math.round((resueltos / totalTickets) * 100) : 0

// **Horas reales de trabajo** = suma de FS vinculados al ticket (vista v_ticket_horas_fs, columna horas_fs).
// Fase 1 (2026-06-03): reemplazó las latencias SLA tiempo_en_cr_h/tiempo_a_fs_h por horas-hombre reales.
function workingHours(r) {
  // Horas reales de trabajo = suma de FS vinculados al ticket (vista v_ticket_horas_fs).
  const h = parseFloat(r.horas_fs);
  return (!isNaN(h) && h > 0) ? h : null;
}

const horasArr = rows.map(workingHours).filter(h => h != null && h > 0)
const horasPromedio = horasArr.length
  ? Math.round((horasArr.reduce((a,b)=>a+b,0) / horasArr.length) * 10) / 10
  : 0
const horasTotalesPeriodo = Math.round(horasArr.reduce((a,b)=>a+b,0) * 10) / 10

const ticketsCriticos = rows.filter(r => HIGH_PRIORITIES.includes(r.priority)).length

// Distribución por categoría (solo si hay 2+)
const cats = {}
rows.forEach(r => { const k = r.category || 'General'; cats[k] = (cats[k]||0)+1 })
const ticketsPorCategoria = Object.entries(cats).sort((a,b)=>b[1]-a[1]).slice(0,8)
  .map(([label,value])=>({label,value}))

// Distribución por técnico
const tecs = {}
rows.forEach(r => { if(r.tecnico_asignado){ tecs[r.tecnico_asignado]=(tecs[r.tecnico_asignado]||0)+1 } })
const ticketsPorTecnico = Object.entries(tecs).sort((a,b)=>b[1]-a[1]).slice(0,8)
  .map(([label,value])=>({label,value}))

// Top 5 tickets más largos (por tiempo real trabajado)
const topLargos = rows
  .map(r => ({ ticket: r.ticket_no, title: r.title || '', status: r.status, priority: r.priority || '', horas: workingHours(r) ?? 0, tecnico: r.tecnico_asignado || '—', category: r.category || '', tiposSoporte: r.tipos_soporte || [], fsNumeros: r.fs_numeros || [] }))
  .filter(t => t.horas > 0)
  .sort((a,b) => b.horas - a.horas)
  .slice(0, 25)

// Distribución por prioridad
const priCount = { High: 0, Medium: 0, Low: 0, Otros: 0 }
rows.forEach(r => {
  const p = r.priority || ''
  if (p === 'High' || p === 'Urgent' || p === 'Alta') priCount.High++
  else if (p === 'Medium' || p === 'Normal') priCount.Medium++
  else if (p === 'Low') priCount.Low++
  else priCount.Otros++
})
const prioridades = Object.entries(priCount).filter(([,v]) => v > 0)
  .map(([label, value]) => ({
    label,
    value,
    color: label === 'High' ? '#F05754' : label === 'Medium' ? '#d4900a' : label === 'Low' ? '#43C961' : '#888',
  }))

// Score: combina pct resolución + tiempos cortos
const score = Math.round(
  pctResolucion * 0.6
  + Math.min(100, Math.max(0, 100 - Math.max(0, horasPromedio - 2) * 10)) * 0.4
)

const charts = { prioridades: prioridades.length >= 2 ? prioridades : [] }
