const narrative = `${totalTickets} tickets en el período, ${resueltos} resueltos (${pctResolucion}%), ${abiertos} abiertos al cierre. ${horasTotalesPeriodo}h de trabajo real total, promedio ${horasPromedio}h por ticket. ${ticketsCriticos} críticos.`;
