const total = hosts.length

// Zabbix host.available: 0=unknown, 1=available, 2=unavailable
// "Online" para nosotros = sin problems activos (más útil que el flag de agent)
const sinProblemas = hosts.filter(h => (h.problems ?? 0) === 0).length
const conProblemas = hosts.filter(h => (h.problems ?? 0) > 0).length
const accesibles   = hosts.filter(h => Number(h.available) === 1).length
const inaccesibles = hosts.filter(h => Number(h.available) === 2).length
const desconocido  = hosts.filter(h => Number(h.available) === 0 || h.available == null).length

const pctSinProblemas = total > 0 ? Math.round((sinProblemas / total) * 100) : 0

// Triggers (alertas activas) por severidad
// Zabbix priority: 0=info, 1=warning, 2=avg, 3=high, 4=disaster, 5=trigger
const sevHigh = triggers.filter(t => Number(t.priority) >= 4).length
const sevMed  = triggers.filter(t => Number(t.priority) === 3).length
const sevLow  = triggers.filter(t => Number(t.priority) >= 1 && Number(t.priority) <= 2).length

const severidad = []
if (sevHigh > 0) severidad.push({ label: 'Crítica/Disaster', value: sevHigh, color: '#F05754' })
if (sevMed > 0)  severidad.push({ label: 'High',              value: sevMed,  color: '#d4900a' })
if (sevLow > 0)  severidad.push({ label: 'Warning/Info',      value: sevLow,  color: '#43C961' })

// Tabla hosts: nombre + estado + alertas + uptime relativo
const tablaHosts = hosts.map(h => ({
  host: h.host || h.name || '?',
  problems: h.problems ?? 0,
  status: Number(h.available) === 1 ? 'OK' : Number(h.available) === 2 ? 'Inaccesible' : 'Desconocido',
  lastChange: h.lastchange_at || h.synced_at || null,
})).sort((a, b) => b.problems - a.problems)

// Tabla alertas activas (top 10 por severidad)
const tablaAlertas = triggers
  .sort((a, b) => Number(b.priority) - Number(a.priority))
  .slice(0, 10)
  .map(t => ({
    severidad: Number(t.priority) >= 4 ? 'Crítica' : Number(t.priority) === 3 ? 'High' : Number(t.priority) >= 1 ? 'Warning' : 'Info',
    host: t.hostname || '?',
    description: t.description || '',
    desde: t.lastchange_at || null,
  }))

// Score: combina hosts ok + cantidad de alertas
const score = Math.round(Math.max(0, pctSinProblemas - sevHigh * 8 - sevMed * 3))


// F4 — narrativas dual
const _alertasTotal = sevHigh + sevMed + sevLow;
const narrative = `${total} servidores monitoreados, ${sinProblemas} sin problemas (${pctSinProblemas}%). ${_alertasTotal} alertas activas (${sevHigh} críticas, ${sevMed} medias, ${sevLow} bajas). ${inaccesibles} inaccesibles para Zabbix.`;
const narrativeClient = `Su infraestructura cuenta con ${total} ${total === 1 ? 'servidor monitoreado' : 'servidores monitoreados'} en tiempo real. ${pctSinProblemas >= 90 ? `${pctSinProblemas}% opera sin incidentes detectados.` : `${pctSinProblemas}% opera sin incidentes; el resto presenta indicadores bajo seguimiento.`} ${sevHigh > 0 ? `${sevHigh} ${sevHigh === 1 ? 'indicador crítico requiere' : 'indicadores críticos requieren'} atención inmediata, ya bajo intervención del equipo técnico.` : _alertasTotal > 0 ? `${_alertasTotal} ${_alertasTotal === 1 ? 'indicador en rango de atención' : 'indicadores en rango de atención'} están siendo evaluados.` : 'No se registran alertas activas.'}`;

return [{ json: {
