// Enriquecer recs con detalle (lista de items afectados, para UI expandible)
function computeDetalle(rec) {
  const inv = getInvRows()
  if (rec.modulo === 'inventario') {
    if (/SO obsoleto/i.test(rec.titulo)) {
      return inv.filter(r => r.eol).map(r => ({
        hostname: r.hostname, so: r.os, build: r.os_version, user: r.user || '',
      }))
    }
    if (/sin contacto/i.test(rec.titulo)) {
      return inv.filter(r => r.stale).map(r => ({
        hostname: r.hostname, lastContact: r.ocs_last_contact, so: r.os, user: r.user || '',
      }))
    }
    if (/sin licencia ESET/i.test(rec.titulo)) {
      return inv.filter(r => !r.has_eset).map(r => ({
        hostname: r.hostname, so: r.os, user: r.user || '', isServer: r.is_server,
      }))
    }
  }
  if (rec.modulo === 'seguridad') {
    if (/detección crítica|detecciones críticas/i.test(rec.titulo)) {
      return getDetecRows().filter(d => d.severity === 'Crítica').slice(0, 30)
    }
    if (/CRITICAL/i.test(rec.titulo)) {
      return getSwRows().filter(s => s.esetStatus === 'CRITICAL').slice(0, 30)
    }
    if (/WARN|Atención/i.test(rec.titulo)) {
      return getSwRows().filter(s => s.esetStatus === 'WARN' || s.esetStatus === 'ATTENTION').slice(0, 30)
    }
    if (/sin reportar/i.test(rec.titulo)) {
      try { return $('transform_seguridad').first().json.tablaSinReportar || [] } catch(_) { return [] }
    }
  }
  if (rec.modulo === 'servidores') {
    if (/alerta|crítica/i.test(rec.titulo)) {
      return getAlertasRows().slice(0, 30)
    }
    if (/inaccesible/i.test(rec.titulo)) {
      return getServidoresRows().filter(s => s.status === 'Inaccesible')
    }
  }
  if (rec.modulo === 'sla') {
    if (/crítico/i.test(rec.titulo)) {
      return getSlaRows().filter(t => t.priority === 'High' || t.priority === 'Urgent').slice(0, 30)
    }
    if (/abierto/i.test(rec.titulo)) {
      return getSlaRows().filter(t => !['Closed','Resuelto','Cerrado/Para Entregar'].includes(t.status)).slice(0, 30)
    }
  }
  return []
}
recs.forEach(rec => { rec.detalle = computeDetalle(rec) })


const PRIO_ORDER = { alta: 0, media: 1, baja: 2 }
recs.sort((a,b) => PRIO_ORDER[a.prioridad] - PRIO_ORDER[b.prioridad])

modules.recomendaciones = {
  narrative: recs.length === 0
    ? 'No se detectaron problemas que requieran acción en el período.'
    : `Se identificaron ${recs.length} ${recs.length===1?'acción recomendada':'acciones recomendadas'} (${recs.filter(r=>r.prioridad==='alta').length} de prioridad alta).`,
  narrativeClient: recs.length === 0
    ? 'No se detectaron oportunidades de mejora prioritarias en el período.'
    : `Se identificaron ${recs.length} ${recs.length===1?'oportunidad de mejora':'oportunidades de mejora'} para el período. ${recs.filter(r=>r.prioridad==='alta').length>0 ? `${recs.filter(r=>r.prioridad==='alta').length} ${plural(recs.filter(r=>r.prioridad==='alta').length,'requiere','requieren')} atención prioritaria.` : 'Todas son de prioridad media o estándar.'}`,
  score: Math.max(0, 100 - recs.filter(r=>r.prioridad==='alta').length * 10 - recs.filter(r=>r.prioridad==='media').length * 5),
  metrics: { items: recs },
  charts: {},
}

// F: respetar la lista de módulos pedida por el user
const requestedMods = Array.isArray(triggerData.modulos) ? triggerData.modulos : null
if (requestedMods && requestedMods.length > 0) {
  for (const key of Object.keys(modules)) {
    if (!requestedMods.includes(key)) delete modules[key]
  }
}

const WEIGHTS = { inventario:0.25, seguridad:0.20, sla:0.20, servidores:0.25, backups:0.10, mantenimiento:0.15 }
const presentes = Object.entries(WEIGHTS).filter(([n]) => modules[n] && !(n === 'mantenimiento' && modules[n].metrics && modules[n].metrics.sinDatos))
const pesoTotal = presentes.reduce((s,[,p]) => s+p, 0)
let healthScore = pesoTotal > 0
  ? Math.round(presentes.reduce((s,[n,p]) => s + modules[n].score * p, 0) / pesoTotal)
  : 0

// Diagnostico (madurez/seguridad) -- blend opcional del ultimo diagnostico definitivo
let diagScore = null, diagNivel = null, diagFecha = null
try {
  const dg = $('sql_diagnostico').first().json
  if (dg && dg.score_total != null) {
    diagScore = Number(dg.score_total)
    diagNivel = dg.nivel_riesgo ?? null
    diagFecha = dg.created_at ? String(dg.created_at).slice(0,10) : null
  }
} catch(_) {}
if (diagScore != null && pesoTotal > 0) {
  const PESO_DIAG = 0.20
  healthScore = Math.round(healthScore * (1 - PESO_DIAG) + diagScore * PESO_DIAG)
}

const invM = modules.inventario?.metrics ?? {}
const secM = modules.seguridad?.metrics  ?? {}
const srvM = modules.servidores?.metrics ?? {}
const slaM = modules.sla?.metrics        ?? {}


// ── Reconciliación de equipos: contrato (Vtiger) vs detectado (OCS/ESET/Mant) ──
// Unión por hostname (normalizado, sin dominio). Un equipo puede estar en una
// consola y no en otra, o sólo en la planilla de mantenimiento — todos cuentan.
const _normH = (h) => String(h || '').trim().toLowerCase().replace(/\.(local|lan|internal|ad)$/, '')
const _hosts = {}
function _addHost(host, src, isSrv) {
  const h = _normH(host); if (!h) return
  const e = _hosts[h] = _hosts[h] || { ocs:false, eset:false, mant:false, srv:false }
  e[src] = true
  if (isSrv) e.srv = true
}
try {
  for (const r of (modules.inventario ? getInvRows() : [])) {
    _addHost(r.hostname, 'ocs', !!r.is_server)
    if (r.has_eset) { const h = _normH(r.hostname); if (_hosts[h]) _hosts[h].eset = true }
  }
} catch(_) {}
const _mant = modules.mantenimiento
if (_mant) {
  for (const t of (_mant.terminales || [])) _addHost(t.hostname, 'mant', false)
  for (const s of (_mant.servidores || [])) _addHost(s.hostname, 'mant', true)
}
const _entries = Object.entries(_hosts)
const _servers = _entries.filter(([, e]) => e.srv)
const _estaciones = _entries.filter(([, e]) => !e.srv)
const _ci = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0 }
const _contratoSrv = _ci(clientData.contrato_servidores) + _ci(clientData.contrato_servidores_virt)
const _contratoEst = _ci(clientData.contrato_estaciones)
const reconciliacion = {
  servidores: {
    contrato: _contratoSrv || null,
    contratoFisicos: clientData.contrato_servidores != null ? _ci(clientData.contrato_servidores) : null,
    contratoVirtuales: clientData.contrato_servidores_virt != null ? _ci(clientData.contrato_servidores_virt) : null,
    detectados: _servers.length,
    faltan: _contratoSrv ? Math.max(0, _contratoSrv - _servers.length) : 0,
    sobran: _contratoSrv ? Math.max(0, _servers.length - _contratoSrv) : 0,
    lista: _servers.map(([h, e]) => ({ hostname: h, ocs: e.ocs, eset: e.eset, mant: e.mant })),
  },
  estaciones: {
    contrato: _contratoEst || null,
    detectados: _estaciones.length,
    faltan: _contratoEst ? Math.max(0, _contratoEst - _estaciones.length) : 0,
    sobran: _contratoEst ? Math.max(0, _estaciones.length - _contratoEst) : 0,
  },
  fuentes: {
    ocs: _entries.filter(([, e]) => e.ocs).length,
    eset: _entries.filter(([, e]) => e.eset).length,
    mant: _entries.filter(([, e]) => e.mant).length,
    zabbix: srvM.total ?? 0,
  },
  // Discrepancias por hostname (para auditar consola vs mantenimiento).
  enConsolaNoMant: _entries.filter(([, e]) => (e.ocs || e.eset) && !e.mant).map(([h]) => h).slice(0, 60),
  enMantNoConsola: _entries.filter(([, e]) => e.mant && !(e.ocs || e.eset)).map(([h]) => h).slice(0, 60),
}

const kpis = {
  uptime:     srvM.pctSinProblemas ?? null,
  tickets:    slaM.totalTickets     ?? 0,
  alertas:    (srvM.alertasActivas ?? 0) + (secM.amenazasCriticas ?? 0),
  servidores: (reconciliacion.servidores.detectados || _contratoSrv || (srvM.total ?? 0)),
  eolHw:      invM.eolCount         ?? 0,
}

const healthBreakdown = {}
for (const [n] of presentes) healthBreakdown[n] = modules[n].score
if (diagScore != null) healthBreakdown.diagnostico = diagScore

const periodo = triggerData.periodo ?? new Date().toISOString().slice(0,7)


// ── TL;DR Executive Summary ──
const altas = recs.filter(r => r.prioridad === 'alta')
const tlDrBullets = []
// Lo mejor (positivo)
if (kpis.uptime != null && kpis.uptime >= 95) {
  tlDrBullets.push({ tone: 'good', text: `Servidores con ${kpis.uptime}% sin incidentes en el período.` })
} else if (kpis.alertas === 0) {
  tlDrBullets.push({ tone: 'good', text: 'Sin alertas activas en infraestructura.' })
}
const _slaTl = modules.sla?.metrics
if (_slaTl && _slaTl.pctResolucion >= 90) {
  tlDrBullets.push({ tone: 'good', text: `${_slaTl.pctResolucion}% de tickets resueltos (${_slaTl.resueltos}/${_slaTl.totalTickets}).` })
}
// Lo crítico
if (altas.length > 0) {
  tlDrBullets.push({ tone: 'critical', text: `${altas.length} ${altas.length === 1 ? 'acción crítica pendiente' : 'acciones críticas pendientes'} de prioridad alta.` })
}
const _invTl = modules.inventario?.metrics
if (_invTl && _invTl.eolCount > 0) {
  tlDrBullets.push({ tone: 'warning', text: `${_invTl.eolCount} ${_invTl.eolCount === 1 ? 'equipo en EOL' : 'equipos en EOL'} sin soporte del fabricante.` })
}
// Próxima acción
if (recs.length > 0) {
  const top = recs[0]
  tlDrBullets.push({ tone: 'next', text: `Próxima acción: ${top.titulo}.` })
}
if (diagScore != null) {
  tlDrBullets.push({ tone: diagScore >= 70 ? 'good' : diagScore >= 45 ? 'warning' : 'critical',
    text: `Madurez de seguridad: ${diagScore}/100${diagFecha ? ` (diagnóstico ${diagFecha})` : ''}.` })
}
const tlDr = {
  healthScore,
  bullets: tlDrBullets.slice(0, 5),
}
modules.__tldr = tlDr

return [{ json: {
  nc:              clientData.nombreCorto,
  periodo,
  tipo:            triggerData.tipo ?? 'mensual',
  generadoAt:      new Date().toISOString(),
  healthScore,
  healthBreakdown,
  kpis,
  modules,
  reconciliacion,
  _meta: {
    informeId: triggerData.informeId,
    modulos:   Object.keys(modules),
  }
} }]

// transform_mantenimiento — input directo: http_mantenimientos (respuesta del endpoint CRM)
// El merge OCS/ESET por hostname se hace en assemble_informe (donde la lectura de
// transform_inventario/transform_seguridad es segura por ordering). Ver regla
// feedback_n8n_exec_order_not_connection_order: un Code node solo lee su INPUT directo.
try {
  const tg = $('webhook_trigger').first().json.body || $('webhook_trigger').first().json
  const tipo = tg.tipo || ''
  const mods = Array.isArray(tg.modulos) ? tg.modulos : null

  // Gate: solo emitir el módulo si el informe lo pidió (tipo standalone o módulo seleccionado).
  // Mantenimiento NO está en presets default → si no se pidió, skip (no contamina healthScore).
  const requested =
    tipo === 'mantenimiento-terminales' ||
    tipo === 'mantenimiento-servidores' ||
    (mods && mods.includes('mantenimiento'))
  if (!requested) return [{ json: { name: 'mantenimiento', skip: true } }]

  const resp = $input.first().json || {}
  const mant = resp && resp.ok && resp.mantenimiento ? resp.mantenimiento : null

  // Endpoint falló (404/503/timeout con neverError) o sin payload → módulo sin datos.
  const metrics = mant && mant.metrics
    ? mant.metrics
    : { sinDatos: true, fecha: null, usadoFallback: false, tecnico: null,
        terminalesTotal: 0, terminalesAlDia: 0, terminalesAtrasados: 0, pctTerminales: 0,
        servidoresTotal: 0, servidoresOk: 0, pctServidores: 0 }

  const m = metrics
  const narrative = m.sinDatos
    ? 'Sin datos de mantenimiento para el período.'
    : `Mantenimiento ${m.fecha || ''}${m.usadoFallback ? ' (última ronda disponible)' : ''}: ` +
      `${m.terminalesAlDia}/${m.terminalesTotal} terminales al día (${m.pctTerminales}%), ` +
      `${m.servidoresOk}/${m.servidoresTotal} servidores OK (${m.pctServidores}%).` +
      `${m.tecnico ? ` Técnico: ${m.tecnico}.` : ''}`
  const narrativeClient = m.sinDatos
    ? 'No se registró una ronda de mantenimiento preventivo en el período.'
    : `Se realizó mantenimiento preventivo sobre ${m.terminalesTotal} ` +
      `${m.terminalesTotal === 1 ? 'equipo' : 'equipos'}` +
      `${m.servidoresTotal ? ` y ${m.servidoresTotal} ${m.servidoresTotal === 1 ? 'servidor' : 'servidores'}` : ''}. ` +
      `${m.pctTerminales}% de los equipos quedaron al día.`

  return [{ json: {
    name: 'mantenimiento',
    narrative,
    narrativeClient,
    score: (mant && typeof mant.score === 'number') ? mant.score : 0,
    metrics,
    charts: {},
    terminales: (mant && mant.terminales) || [],
    servidores: (mant && mant.servidores) || [],
    // Contrato Vtiger (frecuencia + cantidades) para al-día y reconciliación.
    frecuencia: (mant && mant.frecuencia) || null,
    contrato: (mant && mant.contrato) || null,
    ai_prompt: `Mantenimiento: ${m.terminalesAlDia}/${m.terminalesTotal} terminales al día, ${m.servidoresOk}/${m.servidoresTotal} servidores OK. Score ${(mant && mant.score) ?? 0}/100.`,
  } }]
} catch (e) {
  throw new Error(`[report-generation] transform_mantenimiento: ${e.message}`)
}
